"""PDF report generation for 4-class Brain Tumor Detection."""

import os
from datetime import datetime

from reportlab.lib import colors
from reportlab.lib.pagesizes import A4
from reportlab.lib.styles import ParagraphStyle, getSampleStyleSheet
from reportlab.lib.units import mm
from reportlab.platypus import (
    Image,
    Paragraph,
    SimpleDocTemplate,
    Spacer,
    Table,
    TableStyle
)

PROJECT = "Brain Tumor Detection - AI Analysis Report"

DISCLAIMER = (
    "This report is generated by an AI-based research prototype. "
    "It is NOT a medical diagnosis. The prediction may be incorrect. "
    "Please consult a qualified medical professional for medical advice."
)


def build_report(scan: dict, image_path: str, model_info: dict, out_path: str) -> str:

    ss = getSampleStyleSheet()

    title = ParagraphStyle(
        "ReportTitle",
        parent=ss["Title"],
        fontSize=20,
        textColor=colors.HexColor("#0A0A0A")
    )

    heading = ParagraphStyle(
        "ReportHeading",
        parent=ss["Heading2"],
        textColor=colors.HexColor("#007A44")
    )

    body = ss["BodyText"]

    tumor = scan["prediction"] == "Tumor Detected"

    when = datetime.fromisoformat(
        scan["created_at"]
    ).strftime("%d %B %Y, %I:%M %p")

    tumor_type = scan.get("tumor_type", "Unknown")

    probabilities = scan.get("probabilities", {})

    story = [
        Paragraph("BRAIN TUMOR DETECTION", title),
        Paragraph(
            "AI Analysis Report",
            ParagraphStyle(
                "Subtitle",
                parent=ss["Heading3"],
                alignment=1
            )
        ),
        Spacer(1, 8 * mm)
    ]

    # Scan information
    rows = [
        ["Scan ID", scan["scan_id"]],
        ["Date & Time", when],
        ["File Name", scan["filename"]],
        ["AI Prediction", scan["prediction"]],
        ["Detected Class", tumor_type.upper()],
        ["Model Confidence", f"{scan['confidence'] * 100:.2f}%"],
        ["Tumor Probability", f"{scan['tumor_probability'] * 100:.2f}%"]
    ]

    table = Table(
        rows,
        colWidths=[45 * mm, 110 * mm]
    )

    table.setStyle(TableStyle([
        ("GRID", (0, 0), (-1, -1), 0.4, colors.HexColor("#CCCCCC")),
        ("BACKGROUND", (0, 0), (0, -1), colors.HexColor("#F0F0F0")),
        ("FONTNAME", (0, 0), (0, -1), "Helvetica-Bold"),
        (
            "TEXTCOLOR",
            (1, 3),
            (1, 3),
            colors.HexColor("#C0392B") if tumor
            else colors.HexColor("#007A44")
        ),
        ("FONTNAME", (1, 3), (1, 3), "Helvetica-Bold"),
        ("PADDING", (0, 0), (-1, -1), 7)
    ]))

    story.extend([
        table,
        Spacer(1, 7 * mm),
        Paragraph("CLASS PROBABILITIES", heading),
        Spacer(1, 3 * mm)
    ])

    # Four-class probabilities
    probability_rows = [
        ["Tumor Class", "Probability"]
    ]

    class_names = [
        "glioma",
        "meningioma",
        "notumor",
        "pituitary"
    ]

    for class_name in class_names:

        probability = probabilities.get(class_name)

        if probability is not None:
            probability_rows.append([
                class_name.upper(),
                f"{float(probability) * 100:.2f}%"
            ])

    probability_table = Table(
        probability_rows,
        colWidths=[75 * mm, 80 * mm]
    )

    probability_table.setStyle(TableStyle([
        ("GRID", (0, 0), (-1, -1), 0.4, colors.HexColor("#CCCCCC")),
        ("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#E8F5E9")),
        ("FONTNAME", (0, 0), (-1, 0), "Helvetica-Bold"),
        ("PADDING", (0, 0), (-1, -1), 7)
    ]))

    story.extend([
        probability_table,
        Spacer(1, 7 * mm),
        Paragraph("UPLOADED MRI IMAGE", heading)
    ])

    # MRI image
    if os.path.exists(image_path):

        story.append(
            Image(
                image_path,
                width=70 * mm,
                height=70 * mm,
                kind="proportional"
            )
        )

    # Model information
    story.extend([
        Spacer(1, 7 * mm),
        Paragraph("MODEL INFORMATION", heading),
        Paragraph(
            f"Architecture: {model_info['name']}<br/>"
            f"Input: {model_info['input']}<br/>"
            f"Output: {model_info['output']}<br/>"
            f"Mode: {model_info['mode']}",
            body
        )
    ])

    if model_info["mode"] == "demo":

        story.append(
            Paragraph(
                "<b>NOTE:</b> No trained model was loaded. "
                "This result is a demo placeholder.",
                body
            )
        )

    # Disclaimer
    story.extend([
        Spacer(1, 8 * mm),
        Paragraph("IMPORTANT MEDICAL DISCLAIMER", heading),
        Paragraph(DISCLAIMER, body)
    ])

    # Generate PDF
    document = SimpleDocTemplate(
        out_path,
        pagesize=A4,
        title=PROJECT,
        leftMargin=20 * mm,
        rightMargin=20 * mm
    )

    document.build(story)

    return out_path